end

function AnnihilationTeamEntry:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local argument = self.controller.Argument.parameters
        if not argument then
            return
        end
        self._questId = checkNumber(argument.questId)  
        local vo = QuestConfMgr:GetInstance():GetQuestVoById(self._questId)
        if not vo then
            return
        end
        self._sceneVo = CfUtils.GetCfVo(AutoIds.IdSetting270, "BattleSceneVo", vo.SceneId)
        if not self._sceneVo then
            return
        end

        local go = GameObject.Find("LoadingPanel")
        if not go then
            go = GameObject.Find("LoadingPanel")
        end
        ---@type UILoadingPanel
        self._loadingUI = GetLuaBehaviour(go, "Game.Behaviours.UILoadingPanel").Env

        local sceneName = self._sceneVo.sceneName
        self._sceneLoader = ResourceModule.LoadBundleAsync("Scenes/".. sceneName ..".unity", nil, true)
        while not self._sceneLoader.IsSuccess do
            cs_coroutine.yield_return()
        end
        if self._sceneLoader.IsError then
            self._sceneLoader:Release(true)
            return
        end
        if not self._sceneLoader.ResultObject then
            self._sceneLoader:Release(true)
            return
        end

        local operation = SceneManager.LoadSceneAsync(sceneName, SceneManagement.LoadSceneMode.Additive)
        operation.allowSceneActivation = false
        if not operation.isDone then
            while operation.progress < 0.8 do
                coroutine.yield()
                self:OnLoadingProgress(checkNumber(operation.progress) * 100)
            end
            operation.allowSceneActivation = true
    
            while not operation.isDone do
                self:OnLoadingProgress(checkNumber(operation.progress) * 100)
                coroutine.yield()
            end
            operation.allowSceneActivation = true
    
            while not operation.isDone do
                self:OnLoadingProgress(checkNumber(operation.progress) * 100)
                coroutine.yield()
            end
        end

        self._loadingUI:Close()
    end))
    return coWait
end

function AnnihilationTeamEntry:OnLoadingProgress(num)
    self._loadingUI:__Progress(num)
end

function AnnihilationTeamEntry:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        CfUtils.RefreshTopCommon(nil, true)
        local sceneName = self._sceneVo.sceneName
        CS.UnityEngine.SceneManagement.SceneManager.UnloadSceneAsync(sceneName)
        if self.sceneLoader then
            self.sceneLoader:Release(true)
            self.sceneLoader = nil
        end

        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return AnnihilationTeamEntry